import sys, hashlib
p = sys.argv[1] if len(sys.argv) > 1 else 'p.patch'
data = open(p, 'rb').read()
h = hashlib.sha256(data).hexdigest()
assert h == 'a8eed31922316f2c47f379bbab94b3f9377a1ee97cc4d7116e292ee163cd25c7', 'unexpected input p.patch sha256 ' + h
lines = data.decode('utf-8', 'surrogateescape').split('\n')
OPS = [["replace", 0, 1, ["From ce80ef1f026482d406f91c75e2bbe1fb4e131099 Mon Sep 17 00:00:00 2001"]], ["replace", 2, 3, ["Date: Thu, 26 Nov 2026 12:26:36 +0000"]], ["replace", 155, 156, ["diff --git a/Phase/src/Phase.cpp b/Phase/src/Phase.cpp"]], ["replace", 170, 200, ["-\t\t\t\t\tunsigned int opIndex,", "-\t\t\t\t\t\tconst vector<bool> & useSpectralIrradianceForReflectance,", "-\t\t\t\t\t\tPhaseKeyMappingGenerator & pkmg,", "-\t\t\t\t\t\tofstream & outCoeffSpecProperties,", "-\t\t\t\t\t\tPhaseGeneralParametersDTO & genDTO,", "-\t\t\t\t\t\tconst vector<DirectionCartesienne> & listDirections) {", "-", "-\tdouble albedo = 0;", "-\tdouble dTauMoy = 0;", "-", "-\tstd::string baseMaterial;", "-\tdouble roughness = 0.05;", "-\tint materialType = 2;", "-\tint baseBSDFType = 0;", "-\tint baseBSDFIndex = 0;", "-", "-\tvector<double>ni(genDTO.numberOfSpectralBands),nt(genDTO.numberOfSpectralBands),", "-\t\t\ttau(genDTO.numberOfSpectralBands), refl(genDTO.numberOfSpectralBands), trans(genDTO.numberOfSpectralBands);", "-", "-\tfor (unsigned int spectralBandIndex = 0; spectralBandIndex < genDTO.numberOfSpectralBands; spectralBandIndex++) {", "-\t\tPropertySpecular specularProperty;", "-", "-\t\tcomputeOpticalPropertiesSpecular(spectralBandIndex, specularPropertyParameters, listDirections, specularProperty, albedo, dTauMoy);", "-\t\tPhaseDAO::readCoeffDiffParametersForSpecularRoughness(specularPropertyParameters.getModelIndex(), specularProperty.roughness);", "-\t\tPhaseDAO::readCoeffDiffParametersForSpecularMaterial(specularPropertyParameters.getModelIndex(), specularProperty.type, specularProperty.baseBSDF, specularProperty.baseBSDFIndex);", "-", "-\t\t//TODO test albeo", "-\t\t// testSpecularAlbedo(specularPropertyParameters.getModelIndex(), specularProperty);"]], ["delete", 203, 204, []], ["replace", 239, 240, ["-\t//\t\t\tgenDTO.luxCoreRenderSceneProperties.ajouterCle(keyRoot.str() + \"temperatureIndex\", std::to_string(tmpIndex));"]], ["delete", 307, 308, []], ["delete", 335, 336, []], ["replace", 428, 430, ["+#include \"materials/SpecularMaterialWriter.hpp\"", "+#include \"materials/LuxCoreMaterialOutput.hpp\""]], ["replace", 431, 433, ["+#include \"containers/phaseModel/OpticalPropertyParameters.hpp\"", "+#include \"database/model/RefractiveIndexDatabaseParameters.hpp\""]], ["replace", 449, 450, ["+\t// (e.g. \"air\"/\"glass\"); the old v5 DAO read of those names is gone."]], ["replace", 472, 473, ["+\t// \"notImpementedYet\" literal is emitted as-is, kept for output parity)."]], ["replace", 474, 475, ["+\t\tbaseMaterial = \"lambertian\";"]], ["replace", 476, 477, ["+\t\tbaseMaterial = \"RPV\";"]], ["replace", 478, 479, ["+\t\tbaseMaterial = \"notImpementedYet\";"]], ["replace", 481, 482, ["+\t\tbaseMaterial = \"notImpementedYet\";"]], ["replace", 484, 485, ["+\t\tbaseMaterial = \"lambertian\";"]]]
out = []
pos = 0
for tag, i1, i2, new in OPS:
    out.extend(lines[pos:i1])
    if tag != 'delete':
        out.extend(new)
    pos = i2
out.extend(lines[pos:])
open(p, 'w', encoding='utf-8', errors='surrogateescape').write('\n'.join(out))
print('repaired', p, '- harmful-only fixes applied')
